"\ndata_base = \"https://data2.juliocostavizz.uk/scouting-data2\"\n\n",
"\nFileAttachment = {\n  // One whole-file request per URL, then reused. Fetching each complete file\n  // in a single request - instead of letting a reader issue many small ranged\n  // reads - is what keeps the dashboard's request count down.\n  const buffers = new Map();\n\n  const load = (url) => {\n    if (!buffers.has(url)) {\n      buffers.set(url, (async () => {\n        const res = await fetch(url);\n        if (!res.ok) throw new Error(res.status + \" \" + res.statusText + \" - \" + url);\n        return res.arrayBuffer();\n      })());\n    }\n    return buffers.get(url);\n  };\n\n  // \"data/kits.csv\"     -> <data_base>/Info/kits.csv\n  // \"data/Asia.parquet\" -> <data_base>/Asia.parquet\n  const urlFor = (path) => {\n    const name = String(path).replace(/^.*\\//, \"\");\n    return /\\.csv$/i.test(name)\n      ? data_base + \"/Info/\" + name\n      : data_base + \"/\" + name;\n  };\n\n  return (path) => {\n    const name = String(path).replace(/^.*\\//, \"\");\n    const url = urlFor(path);\n    return {\n      name,\n      url: () => url,\n      arrayBuffer: () => load(url),\n      async text() {\n        return new TextDecoder(\"utf-8\").decode(await load(url));\n      },\n      async blob() {\n        return new Blob([await load(url)]);\n      },\n      async json() {\n        return JSON.parse(await this.text());\n      },\n      // Mirrors the stdlib signature: .csv() and .csv({ typed: true })\n      async csv({ typed = false, array = false } = {}) {\n        const text = await this.text();\n        const parse = array ? d3.csvParseRows : d3.csvParse;\n        return typed ? parse(text, d3.autoType) : parse(text);\n      }\n    };\n  };\n}\n\n",
