"\ngetPitchLines = {\n  const lines = [];\n  // left penalty box\n  lines.push({\n    x1: 0,\n    x2: 16.5,\n    y1: pitchHeight / 2 - 11 - 9.15,\n    y2: pitchHeight / 2 - 11 - 9.15\n  });\n  lines.push({\n    x1: 16.5,\n    x2: 16.5,\n    y1: 13.85,\n    y2: pitchHeight / 2 + 11 + 9.15\n  });\n  lines.push({\n    x1: 0,\n    x2: 16.5,\n    y1: pitchHeight / 2 + 11 + 9.15,\n    y2: pitchHeight / 2 + 11 + 9.15\n  });\n  // left six-yard box\n  lines.push({\n    x1: 0,\n    x2: 5.5,\n    y1: pitchHeight / 2 - 9.15,\n    y2: pitchHeight / 2 - 9.15\n  });\n  lines.push({\n    x1: 5.5,\n    x2: 5.5,\n    y1: pitchHeight / 2 - 9.15,\n    y2: pitchHeight / 2 + 9.15\n  });\n  lines.push({\n    x1: 0,\n    x2: 5.5,\n    y1: pitchHeight / 2 + 9.15,\n    y2: pitchHeight / 2 + 9.15\n  });\n  // right penalty box\n  lines.push({\n    x1: pitchWidth - 16.5,\n    x2: pitchWidth,\n    y1: pitchHeight / 2 - 11 - 9.15,\n    y2: pitchHeight / 2 - 11 - 9.15\n  });\n  lines.push({\n    x1: pitchWidth - 16.5,\n    x2: pitchWidth - 16.5,\n    y1: pitchHeight / 2 - 11 - 9.15,\n    y2: pitchHeight / 2 + 11 + 9.15\n  });\n  lines.push({\n    x1: pitchWidth - 16.5,\n    x2: pitchWidth,\n    y1: pitchHeight / 2 + 11 + 9.15,\n    y2: pitchHeight / 2 + 11 + 9.15\n  });\n  // right six-yard box\n  lines.push({\n    x1: pitchWidth - 5.5,\n    x2: pitchWidth,\n    y1: pitchHeight / 2 - 9.15,\n    y2: pitchHeight / 2 - 9.15\n  });\n  lines.push({\n    x1: pitchWidth - 5.5,\n    x2: pitchWidth - 5.5,\n    y1: pitchHeight / 2 - 9.15,\n    y2: pitchHeight / 2 + 9.15\n  });\n  lines.push({\n    x1: pitchWidth - 5.5,\n    x2: pitchWidth,\n    y1: pitchHeight / 2 + 9.15,\n    y2: pitchHeight / 2 + 9.15\n  });\n  // outside borders\n  lines.push({ x1: 0, x2: pitchWidth, y1: 0, y2: 0 });\n  lines.push({ x1: 0, x2: pitchWidth, y1: pitchHeight, y2: pitchHeight });\n  lines.push({ x1: 0, x2: 0, y1: 0, y2: pitchHeight });\n  lines.push({ x1: pitchWidth, x2: pitchWidth, y1: 0, y2: pitchHeight });\n  // middle line\n  lines.push({\n    x1: pitchWidth / 2,\n    x2: pitchWidth / 2,\n    y1: 0,\n    y2: pitchHeight\n  });\n  // left goal\n  lines.push({\n    x1: -1.5,\n    x2: -1.5,\n    y1: pitchHeight / 2 - 7.32 / 2,\n    y2: pitchHeight / 2 + 7.32 / 2\n  });\n  lines.push({\n    x1: -1.5,\n    x2: 0,\n    y1: pitchHeight / 2 - 7.32 / 2,\n    y2: pitchHeight / 2 - 7.32 / 2\n  });\n  lines.push({\n    x1: -1.5,\n    x2: 0,\n    y1: pitchHeight / 2 + 7.32 / 2,\n    y2: pitchHeight / 2 + 7.32 / 2\n  });\n  // right goal\n  lines.push({\n    x1: pitchWidth + 1.5,\n    x2: pitchWidth + 1.5,\n    y1: pitchHeight / 2 - 7.32 / 2,\n    y2: pitchHeight / 2 + 7.32 / 2\n  });\n  lines.push({\n    x1: pitchWidth,\n    x2: pitchWidth + 1.5,\n    y1: pitchHeight / 2 - 7.32 / 2,\n    y2: pitchHeight / 2 - 7.32 / 2\n  });\n  lines.push({\n    x1: pitchWidth,\n    x2: pitchWidth + 1.5,\n    y1: pitchHeight / 2 + 7.32 / 2,\n    y2: pitchHeight / 2 + 7.32 / 2\n  });\n  return lines;\n}\n\n\n",
