"\ngetArcs = {\n  const arcs = [];\n  const penaltyRadius = 9.15;\n  const cornerRadius = 1;\n\n  // left top corner\n  arcs.push({\n    arc: {\n      innerRadius: cornerRadius,\n      outerRadius: cornerRadius,\n      startAngle: Math.PI / 2,\n      endAngle: Math.PI\n    },\n    x: 0,\n    y: 0 // In D3 SVG coordinates, Y=0 is the top\n  });\n\n  // Left Bottom Corner (Quadrant: Top-Right)\n  // Needs to go from 12 o'clock (0) to 3 o'clock (PI/2)\n  arcs.push({\n    arc: {\n      innerRadius: cornerRadius,\n      outerRadius: cornerRadius,\n      startAngle: 0,\n      endAngle: Math.PI / 2\n    },\n    x: 0,\n    y: pitchHeight\n  });\n\n  // Right Top Corner (Quadrant: Bottom-Left)\n  // Needs to go from 6 o'clock (PI) to 9 o'clock (3PI/2)\n  arcs.push({\n    arc: {\n      innerRadius: cornerRadius,\n      outerRadius: cornerRadius,\n      startAngle: Math.PI,\n      endAngle: (3 * Math.PI) / 2\n    },\n    x: pitchWidth,\n    y: 0\n  });\n\n  // Right Bottom Corner (Quadrant: Top-Left)\n  // Needs to go from 9 o'clock (3PI/2) to 12 o'clock (2PI)\n  arcs.push({\n    arc: {\n      innerRadius: cornerRadius,\n      outerRadius: cornerRadius,\n      startAngle: (3 * Math.PI) / 2,\n      endAngle: 2 * Math.PI\n    },\n    x: pitchWidth,\n    y: pitchHeight\n  });\n  // left penalty arc\n  // left penalty arc\n  arcs.push({\n    arc: {\n      innerRadius: penaltyRadius,\n      outerRadius: penaltyRadius,\n      startAngle: Math.sin(6.5 / 9.15),\n      endAngle: Math.PI - Math.sin(6.5 / 9.15)\n    },\n    x: 11,\n    y: pitchHeight / 2\n  });\n  // right penalty arc\n  arcs.push({\n    arc: {\n      innerRadius: penaltyRadius,\n      outerRadius: penaltyRadius,\n      startAngle: -Math.sin(6.5 / 9.15),\n      endAngle: -(Math.PI - Math.sin(6.5 / 9.15))\n    },\n    x: pitchWidth - 11,\n    y: pitchHeight / 2\n  });\n  return arcs;\n  return arcs;\n}\n\n\n",
"LEAGUE_LOGO_ALIAS = ({\n  // \"Brazil|Serie A\": \"Brasileirao Serie A\",\n})",
"getleagueLogoURL = (league) => {\n  const name = LEAGUE_LOGO_ALIAS[league] ?? league ?? \"\";\n  return `https://cdn.jsdelivr.net/gh/JulioCosta555/Leagues@main/${encodeURIComponent(fixMojibake(String(name)).normalize(\"NFD\"))}.png`;\n}",
"kit_colors = FileAttachment(\"data/kits.csv\").csv()\n\n// The charts look colours up by teamShortName and read .HomeKit / .HomeKit2.\n// teamOfficialName in the kits file = teamFullName in proccessdata.csv,\n// so map each teamShortName → its official name's colour.",
"kit_color_map = {\n  const byOfficial = new Map(\n    kit_colors\n      .filter(r => r.teamOfficialName && r.Kit_Color)\n      .map(r => [r.teamOfficialName.trim(), r.Kit_Color.trim()])\n  );\n  const m = new Map();\n  for (const d of proc_raw) {\n    const colour = byOfficial.get(String(d.teamFullName ?? \"\").trim());\n    if (!colour || !d.teamShortName) continue;\n    const entry = { Team: d.teamShortName, HomeKit: colour, HomeKit2: colour };\n    m.set(d.teamShortName, entry);\n    m.set(fixMojibake(d.teamShortName), entry);\n  }\n  return m;\n}",
"\nxT_grid = [\n  [0.00638303, 0.00779616, 0.00844854, 0.00977659, 0.01126267, 0.01248344, 0.01473596, 0.01745060, 0.02122129, 0.02756312, 0.03485072, 0.03792590],\n  [0.00750072, 0.00878589, 0.00942382, 0.01059490, 0.01214719, 0.01384540, 0.01611813, 0.01870347, 0.02401521, 0.02953272, 0.04066992, 0.04647721],\n  [0.00887990, 0.00977745, 0.01001304, 0.01110462, 0.01269174, 0.01429128, 0.01685596, 0.01935132, 0.02412240, 0.02855202, 0.05491138, 0.06442595],\n  [0.00941056, 0.01082722, 0.01016549, 0.01132376, 0.01262646, 0.01484598, 0.01689528, 0.01997070, 0.02385149, 0.03511326, 0.10805102, 0.25745362],\n  [0.00941056, 0.01082722, 0.01016549, 0.01132376, 0.01262646, 0.01484598, 0.01689528, 0.01997070, 0.02385149, 0.03511326, 0.10805102, 0.25745362],\n  [0.00887990, 0.00977745, 0.01001304, 0.01110462, 0.01269174, 0.01429128, 0.01685596, 0.01935132, 0.02412240, 0.02855202, 0.05491138, 0.06442595],\n  [0.00750072, 0.00878589, 0.00942382, 0.01059490, 0.01214719, 0.01384540, 0.01611813, 0.01870347, 0.02401521, 0.02953272, 0.04066992, 0.04647721],\n  [0.00638303, 0.00779616, 0.00844854, 0.00977659, 0.01126267, 0.01248344, 0.01473596, 0.01745060, 0.02122129, 0.02756312, 0.03485072, 0.03792590]\n]\n\n",
"addXT = (events) => {\n  if (!Array.isArray(events)) {\n    throw new Error(\"addXT: input must be an array\");\n  }\n\n  const assignBin = (a, b) => {\n    let col, row;\n\n    if (a % 8.33 === 0) {\n      col = Math.floor(a / 8.33);\n    } else {\n      col = Math.floor(a / 8.33) + 1;\n      if (col > 12) col = 12;\n    }\n\n    if (b % 12.5 === 0) {\n      row = Math.floor(b / 12.5);\n    } else {\n      row = Math.floor(b / 12.5) + 1;\n      if (row > 8) row = 8;\n    }\n\n    const r = Math.max(0, Math.min(7, row - 1));\n    const c = Math.max(0, Math.min(11, col - 1));\n    return [r, c];\n  };\n\n  const lookupXT = (x, y) => {\n    if (x == null || y == null || isNaN(+x) || isNaN(+y)) return null;\n    const [r, c] = assignBin(+x, +y);\n    return xT_grid[r][c];\n  };\n\n  return events.map(e => ({\n    ...e,\n    xTStart: lookupXT(e.x, e.y),\n    xTEnd: lookupXT(e.EndX, e.EndY)\n  }));\n}",
